export interface CanonicalEvidenceType {
  description: string;
  category: string;
  aliases: string[];
}

export const CANONICAL_EVIDENCE_TYPES: Record<string, CanonicalEvidenceType> = {
  "access_logs": {"description":"Access/authentication log records (e.g., login activity, access attempts).","category":"SystemLogs","aliases":[]},
  "audit_reports": {"description":"Audit records/reports: review results, audit trail evidence, independent assessment artifacts.","category":"Documents","aliases":["update_status"]},
  "backup_logs": {"description":"Backup and restore records (success/failure, retention).","category":"BackupFiles","aliases":[]},
  "encryption_policies": {"description":"Encryption configuration and policy evidence (at-rest/in-transit encryption, key management).","category":"SecurityPolicies","aliases":["s3_encryption","s3_public_access","iam_mfa"]},
  "event_logs": {"description":"System/event/audit log evidence from the endpoint or cloud.","category":"SystemLogs","aliases":["event_logs"]},
  "firewall_configs": {"description":"Firewall state and rule configuration evidence.","category":"ConfigFiles","aliases":["firewall"]},
  "incident_reports": {"description":"Incident/breach reports and response records.","category":"Documents","aliases":["incident_reports"]},
  "network_configs": {"description":"Network configuration evidence (interfaces, segmentation, routing).","category":"NetworkConfigs","aliases":["network"]},
  "policy_document": {"description":"Written policy/standard/procedure documents.","category":"Documents","aliases":["policy_document"]},
  "security_policies": {"description":"Security configuration/policy evidence from the endpoint (password policy, audit policy, hardening).","category":"SecurityPolicies","aliases":["security_policies","security_settings"]},
  "system_configs": {"description":"System/OS configuration evidence (services, installed software, file permissions, system info).","category":"ConfigFiles","aliases":["system_info","services","software","file_permissions"]},
  "training_records": {"description":"Security awareness/competency training records.","category":"Documents","aliases":["training_records"]},
  "user_provisioning": {"description":"User account/provisioning evidence (account inventory, MFA enforcement, access reviews).","category":"Documents","aliases":["users","iam_policy","iam_mfa"]},
};

/** Map a canonical evidence type to its desktop storage category. */
export function getCategoryForType(evidenceType: string): string {
  return CANONICAL_EVIDENCE_TYPES[evidenceType]?.category ?? "Documents";
}
